import re
LINE = re.compile(r"^(?P<level>[IWEF])(?P<timestamp>\d{4} \d{2}:\d{2}:\d{2}\.\d+)\s+(?P<pid>\d+) "
                  r"(?P<source>\S+\.go:\d+)\] (?P<message>\S.*?)\s*$")
CLOSE = re.compile(r"^\s*>\s*$")

def parse(lines):
    recs, used = [], []
    cur = None
    for j, ln in enumerate(lines):
        if not ln.strip():
            continue
        m = LINE.match(ln)
        if m:
            cur = m.groupdict()
            recs.append(cur)
            used.append(j)
            continue
        if cur is None:
            continue
        # a continuation of the record above: the body of a multi-line
        # value (key=< ... >) or any other wrapped text
        if CLOSE.match(ln):
            cur["message"] = cur["message"].rstrip() + ">"
        else:
            sep = "" if cur["message"].endswith("=<") else " "
            cur["message"] = cur["message"] + sep + ln.strip()
        used.append(j)
    return {"blocks": [{"name": "log lines", "kind": "table", "lines": used, "records": recs}],
            "skip": []}
